import{_ as e,o as a,c as d,a3 as o}from"./chunks/framework.BM_-pWjS.js";const b=JSON.parse('{"title":"ラベリング","description":"","frontmatter":{},"headers":[],"relativePath":"ja/labeling.md","filePath":"ja/labeling.md"}'),r={name:"ja/labeling.md"};function c(n,t,i,l,h,s){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="ラベリング" tabindex="-1">ラベリング <a class="header-anchor" href="#ラベリング" aria-label="Permalink to &quot;ラベリング&quot;">​</a></h1><h2 id="なぜラベリングが必要か" tabindex="-1">なぜラベリングが必要か <a class="header-anchor" href="#なぜラベリングが必要か" aria-label="Permalink to &quot;なぜラベリングが必要か&quot;">​</a></h2><p>RAW+JPG 同時撮影をすると、撮影後のフォルダには「撮って出し JPEG」「RAW」「現像済みファイル」が混在します。ファイル名だけでは種別の見分けがつかず、どれが現像済みでどれがまだかを把握するのに時間がかかるため、セレクト作業を始める前に各ファイルが現在ワークフローのどの段階にあるかを即座に把握できる必要があります。そこで bridge-lite はフォルダを開くと自動的に各ファイルを解析し、拡張子・EXIF の Software タグ・ファイル名のステムを組み合わせて種別を判定し、結果を各サムネイルにバッジとして表示します。これにより、サムネイルグリッドを見るだけで撮って出し・RAW・現像済みの区別がひと目でわかり、現像の抜け漏れや RAW だけをセレクトしてしまう事故を防ぎます。</p><h2 id="バッジの種類" tabindex="-1">バッジの種類 <a class="header-anchor" href="#バッジの種類" aria-label="Permalink to &quot;バッジの種類&quot;">​</a></h2><table tabindex="0"><thead><tr><th>バッジ</th><th>意味</th><th>判定方法</th></tr></thead><tbody><tr><td><code>SOOC</code></td><td>撮って出し（カメラ JPEG）</td><td>拡張子が JPEG かつ EXIF Software タグが現像ソフトでない</td></tr><tr><td><code>RAW</code></td><td>RAW ファイル</td><td>拡張子（<code>.arw</code> / <code>.cr3</code> / <code>.nef</code> 等）</td></tr><tr><td><code>現像済み</code></td><td>現像済みバリアント</td><td>EXIF Software タグに Lightroom・Capture One 等のキーワードを含む</td></tr><tr><td><code>判定不能</code></td><td>種別を自動判定できなかったファイル</td><td>上記いずれにも該当しない</td></tr></tbody></table><h2 id="判定が外れる可能性があるケース" tabindex="-1">判定が外れる可能性があるケース <a class="header-anchor" href="#判定が外れる可能性があるケース" aria-label="Permalink to &quot;判定が外れる可能性があるケース&quot;">​</a></h2><p>自動判定はヒューリスティクスに基づいており、以下のケースでは誤判定が起こることがあります。</p><p><strong>EXIF が存在しないファイル</strong> EXIF データが含まれていないファイルは、Software タグによる判定ができません。現像済みかどうかを判断できず、<code>判定不能</code> になる場合があります。</p><p><strong>EXIF を意図的に削除したファイル</strong> 納品前の EXIF 削除など、意図的に EXIF が取り除かれたファイルは pHash（知覚ハッシュ）による視覚的類似度のみでグループ化されます。構図が似た別カットと誤ってグループ化されるリスクがあります。</p><p><strong>既知でない現像ソフトで書き出したファイル</strong> EXIF の Software タグが bridge-lite の既知リストに含まれない現像ソフト名の場合、<code>現像済み</code> と判定されず <code>判定不能</code> または <code>SOOC</code> になることがあります。</p><p><strong>ファイル名が DCF 命名規則に従わないカメラ</strong> カメラメーカーの標準的な DCF 命名（<code>DSC00001</code> 等）に従わないファイル名の場合、別カットとの誤グループ化が起きやすくなります。</p><h2 id="重複バッジ" tabindex="-1">重複バッジ <a class="header-anchor" href="#重複バッジ" aria-label="Permalink to &quot;重複バッジ&quot;">​</a></h2><p>バイト単位で完全に同一のファイルが複数存在する場合、重複バッジが表示されます。誤って同じ現像結果を複数回書き出してしまったケースなどで役立ちます。</p><p>判定は2段階で行われます。まずファイルサイズが一致するファイルだけを候補として絞り込み、次にその候補に対してのみ SHA-256 ハッシュを計算します。SHA-256 が一致したファイルを重複と判定するため、ファイル名が異なっていても内容が同一であれば検出されます。ハッシュ値はキャッシュされるため、2回目以降の判定は高速です。</p>',14)])])}const _=e(r,[["render",c]]);export{b as __pageData,_ as default};
